@classmethod
def _find_variable_definitions(cls, tree):
    """Find variables defined in the tree via assignment.

    This handles both standard assignments (``{% set x = ... %}``) and
    block assignments (``{% set x %}...{% endset %}``, Jinja 2.8+).
    ``meta.find_undeclared_variables`` does not count block-assignment
    targets as declarations, so we collect them here to avoid false
    positives.
    """
    defined = set()
    for elem in tree.find_all(jinja2.nodes.Assign):
        target = elem.target
        if isinstance(target, jinja2.nodes.Name):
            defined.add(target.name)
    for elem in tree.find_all(jinja2.nodes.AssignBlock):
        target = elem.target
        if isinstance(target, jinja2.nodes.Name):
            defined.add(target.name)
    return defined

